    hazards.push({ x: 340, y: floorY - 18, w: 220, h: 28, type: h2Type });

    // Right lower safe + optional third hazard
    solids.push({ x: 580, y: 420, w: 140, h: 18 });
    if (Math.random() < 0.7) {
      const h3Type = Math.random() < 0.5 ? "lava" : "water";
      hazards.push({ x: 730, y: floorY - 18, w: irand(70, 100), h: 28, type: h3Type });
