    solids.push({ x: 680 + irand(-20, 20), y: 200 + irand(-15, 15), w: 100, h: 16 });
210→    solids.push({ x: 800, y: 160, w: 140, h: 18 });
    solids.push({ x: 780, y: 300 + irand(-10, 20), w: 120, h: 16 });

    // Small stepping stones
    solids.push({ x: 300 + irand(-15, 15), y: 470, w: 36, h: 14 });
    solids.push({ x: 480 + irand(-20, 20), y: 470, w: 36, h: 14 });

    // Ceiling bits / walls for flavor
