    solids.push({ x: 150, y: 100, w: 80, h: 14 });
220→
    // Doors (exits)
    doors.push({ x: 860, y: 100, w: 36, h: 60, type: "fire", done: false });
    doors.push({ x: 900, y: 100, w: 36, h: 60, type: "water", done: false });
    // Door platform already there

    // Gems — random subset of anchor spots
    const gemSpots = [
      { x: 90, y: 380, c: "fire" },
      { x: 250, y: 390, c: "water" },
230→      { x: 420, y: 320, c: "fire" },
      { x: 560, y: 260, c: "water" },
      { x: 100, y: 240, c: "water" },
      { x: 240, y: 190, c: "fire" },
